function ensureLeadTasks(t){if(!Array.isArray(t.leadTasks)||!t.leadTasks.length){t.leadTasks=defaultLeadTasks();let old=LEAD_TASKS.indexOf(t.currentLeadTask);if(old>=0)for(let i=0;i<=old;i++)t.leadTasks[i].status='Complete'}else{let by=new Map(t.leadTasks.map(x=>[x.name,x]));t.leadTasks=LEAD_TASKS.map((name,i)=>Object.assign({name,status:/customer source/i.test(name)?'Requirement TBD':'Not Started',order:i+1,notes:''},by.get(name)||{}))}return t.leadTasks}
