function operationalFocus(){let a=activeTools(),issues=[];a.forEach(t=>{let rem=leadRemaining(t),pf=performance(t)[0];if(rem.some(x=>/request options/i.test(x.name)&&x.status==='Not Started'))issues.push({level:'critical',tool:t.id,text:'Options request not started'});else if(rem.some(x=>x.status==='Requirement TBD'))issues.push({level:'attention',tool:t.id,text:'Lead/Admin requirement still TBD'});if(pf==='BEHIND')issues.push({level:'attention',tool:t.id,text:'Behind Micro Schedule'});if(t.ncs.some(n=>n.state==='Escalated'))issues.push({level:'critical',tool:t.id,text:'Escalated NC requires attention'});if(t.toolStatus==='Packing'&&shippingProgress(t)<100)issues.push({level:'attention',tool:t.id,text:'Packing handoffs incomplete'})});let crit=issues.filter(x=>x.level==='critical'),att=issues.filter(x=>x.level==='attention'),on=Math.max(0,a.length-new Set(issues.map(x=>x.tool)).size);return `<section class="panel focus-panel"><div class="panel-head"><h2>OPERATIONAL FOCUS</h2><span class="live-auto">AUTO · LIVE</span></div><div class="focus-summary"><div><b>${crit.length}</b><span>CRITICAL</span></div><div><b>${att.length}</b><span>ATTENTION</span></div><div><b>${on}</b><span>ON TRACK</span></div></div><div class="focus-list">${issues.slice(0,8).map(x=>`<div class="focus-item ${x.level}" data-tool="${esc(x.tool)}"><b>${esc(x.tool)}</b><span>${esc(x.text)}</span></div>`).join('')||'<div class="focus-clear">✓ NO CURRENT AUTOMATED ATTENTION ITEMS</div>'}</div></section>`}
